import { createAction, createAsyncAction } from 'typesafe-actions';
import { LoadUserPayload, User } from '@appTypes/user.type';

export const addUser = createAction('ADD_USER', (name: string) => ({
  id: 'FETCH_ID',
  name,
}))<User>();

export const removeUser = createAction('REMOVE_USER')<string>();

export const loadUsersAsync = createAsyncAction(
  'LOAD_USERS_REQUEST',
  'LOAD_USERS_SUCCESS',
  'LOAD_USERS_FAILURE'
)<LoadUserPayload, User[], string>();

