import { combineReducers } from "redux";
import { createReducer } from "typesafe-actions";

import { InitialUserInfo} from "@appTypes/user.type";
import { ActionDispatcherType } from "@appTypes/app.type";
import { loadUsersAsync } from "@actions/user.action";

const initialUser: InitialUserInfo = {
  profile: {
    id: ""
  }
}

const UserReducer = combineReducers({
  users: createReducer<InitialUserInfo>(initialUser)
    .handleAction(
      loadUsersAsync.success,
      (state: InitialUserInfo, action: ActionDispatcherType) => {
        console.log("action", action);
        
        return {
          ...state
        }
      }
    )
});

export default UserReducer;
